PRAGMA foreign_keys = ON;
CREATE TABLE users(id TEXT PRIMARY KEY, auth_subject TEXT NOT NULL UNIQUE, email TEXT NOT NULL UNIQUE, role TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('student','admin')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products(sku TEXT PRIMARY KEY CHECK(sku='MSV-FUN-001'),name TEXT NOT NULL,currency TEXT NOT NULL CHECK(currency='PEN'),price_minor INTEGER NOT NULL CHECK(price_minor=6700),active INTEGER NOT NULL DEFAULT 0 CHECK(active IN (0,1)));
INSERT INTO products(sku,name,currency,price_minor) VALUES('MSV-FUN-001','Funciones desde Cero para la Universidad','PEN',6700);
CREATE TABLE orders(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),sku TEXT NOT NULL REFERENCES products(sku),amount_minor INTEGER NOT NULL CHECK(amount_minor=6700),currency TEXT NOT NULL CHECK(currency='PEN'),provider TEXT NOT NULL CHECK(provider IN ('mercadopago','yape_manual')),status TEXT NOT NULL DEFAULT 'pending',external_reference TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX orders_user ON orders(user_id,created_at);
CREATE TABLE payments(provider_payment_id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),provider_status TEXT NOT NULL,amount_minor INTEGER NOT NULL,currency TEXT NOT NULL,provider_updated_at TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payment_events(id INTEGER PRIMARY KEY,provider TEXT NOT NULL,event_key TEXT NOT NULL,resource_id TEXT NOT NULL,signature_valid INTEGER NOT NULL CHECK(signature_valid=1),processed INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider,event_key));
CREATE TABLE entitlements(user_id TEXT NOT NULL REFERENCES users(id),sku TEXT NOT NULL REFERENCES products(sku),source_order_id TEXT NOT NULL REFERENCES orders(id),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,sku,source_order_id));
CREATE INDEX entitlements_lookup ON entitlements(user_id,sku,active);
CREATE TABLE modules(id TEXT PRIMARY KEY,sku TEXT NOT NULL REFERENCES products(sku),title TEXT NOT NULL,position INTEGER NOT NULL);
CREATE TABLE lessons(id TEXT PRIMARY KEY,module_id TEXT NOT NULL REFERENCES modules(id),title TEXT NOT NULL,body TEXT NOT NULL,video_key TEXT,position INTEGER NOT NULL);
CREATE TABLE questions(id TEXT PRIMARY KEY,lesson_id TEXT NOT NULL REFERENCES lessons(id),kind TEXT NOT NULL CHECK(kind IN ('multiple_choice','exact_number','set')),prompt TEXT NOT NULL,options_json TEXT,private_rule_json TEXT NOT NULL,explanation TEXT NOT NULL,difficulty INTEGER NOT NULL CHECK(difficulty BETWEEN 1 AND 5));
CREATE TABLE attempts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),question_id TEXT NOT NULL REFERENCES questions(id),answer_json TEXT NOT NULL,correct INTEGER NOT NULL CHECK(correct IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX attempts_user ON attempts(user_id,question_id,created_at);
CREATE TABLE progress(user_id TEXT NOT NULL REFERENCES users(id),lesson_id TEXT NOT NULL REFERENCES lessons(id),completed INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,lesson_id));
CREATE TABLE admin_audit_logs(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,resource_id TEXT NOT NULL,context_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE manual_payment_reviews(id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),reviewer_id TEXT REFERENCES users(id),verification_method TEXT,reviewed_at TEXT);
